    counts = Counter(v for row in grid for v in row if v != 0)
    color = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]

    variants = set()
    for flip in (1, -1):
        for turns in range(4):
            q = [(r, flip*c) for r, c in shape]
            for _ in range(turns):
                q = [(c, -r) for r, c in q]
            mr, mc = min(r for r, c in q), min(c for r, c in q)
            variants.add(tuple(sorted((r-mr, c-mc) for r, c in q)))

    out = [row[:] for row in grid]
    for shape in variants:
        sh = max(r for r, c in shape) + 1
        sw = max(c for r, c in shape) + 1
        for top in range(h-sh+1):
            for left in range(w-sw+1):
                cells = [(top+r, left+c) for r, c in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
